// TypeScript definitions for the C3 type Duration

/**
 * A duration is a measurement of elapsed time in microseconds.  This can be naturally represented as a string of the
 * form "5h3m45s350ms", which is used as the serialization format.
 *
 * @see Period
 *
 * @remarks this represents a value passed to a method that expects an instance of Duration
 */
declare interface IDuration {

  NANOS_IN_MICROS: number;

  NANOS_IN_MILLIS: number;

  NANOS_IN_SEC: number;

  NANOS_IN_MIN: number;

  MICROS_IN_MILLIS: number;

  MICROS_IN_SEC: number;

  MICROS_IN_MIN: number;

  MILLIS_IN_SEC: number;

  MILLIS_IN_MIN: number;

  MILLIS_IN_HOUR: number;

  microseconds: number;
}

